-- 590_le_domande_dei_clienti_avvisano_il_negozio.sql
--
-- R02-007 — LE DOMANDE SOTTO I PRODOTTI NON ARRIVAVANO A NESSUNO.
--
-- Una domanda entra in product_questions (027) e resta li': nessun avviso al
-- negozio, nessun avviso a chi l'ha fatta quando arriva la risposta. Il testo
-- sotto il prodotto non promette piu' una notifica (components/ProductQA.tsx:95-96),
-- ma il negozio la domanda la trova solo se apre la scheda per caso.
--   ① AFTER INSERT: un avviso al negozio del prodotto (products.seller_id), col
--      link alla pagina «Domande da rispondere» (/seller/domande);
--   ② AFTER UPDATE OF answer: alla PRIMA risposta (prima vuota, ora scritta) su
--      una domanda visibile, un avviso a chi l'ha fatta, col link alla scheda.
-- Categoria 'system' (115): un avviso di servizio, che vuole_notifica() non spegne.
-- Un avviso che non si scrive non ferma ne' la domanda ne' la risposta.
-- Non si applica da sola: la applica Nicola.

CREATE OR REPLACE FUNCTION public.domanda_avvisa_il_negozio()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_negozio  uuid;
  v_prodotto text;
BEGIN
  SELECT p.seller_id, p.name INTO v_negozio, v_prodotto
    FROM public.products p
   WHERE p.id = NEW.product_id;
  -- Nessun negozio (seller_id ON DELETE SET NULL, 001) o il negozio che chiede a se stesso: niente avviso.
  IF v_negozio IS NULL OR v_negozio = NEW.author_id THEN
    RETURN NEW;
  END IF;
  BEGIN
    INSERT INTO public.notifications (user_id, title, body, link, category)
    VALUES (
      v_negozio,
      'Nuova domanda su ' || coalesce(v_prodotto, 'un tuo prodotto'),
      left(NEW.question, 140),
      '/seller/domande',
      'system'
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'domanda_avvisa_il_negozio: avviso non scritto per la domanda %: %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.risposta_avvisa_chi_ha_chiesto()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_prodotto text;
BEGIN
  -- Solo la prima risposta, solo su una domanda che si vede, e non a chi risponde a se stesso.
  IF NEW.answer IS NULL OR btrim(NEW.answer) = ''
     OR OLD.answer IS NOT NULL
     OR NEW.is_public IS NOT TRUE
     OR NEW.answered_by IS NOT DISTINCT FROM NEW.author_id THEN
    RETURN NEW;
  END IF;
  SELECT p.name INTO v_prodotto FROM public.products p WHERE p.id = NEW.product_id;
  BEGIN
    INSERT INTO public.notifications (user_id, title, body, link, category)
    VALUES (
      NEW.author_id,
      'Il negozio ha risposto alla tua domanda',
      coalesce(v_prodotto || ': ', '') || left(NEW.answer, 140),
      '/product/' || NEW.product_id,
      'system'
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'risposta_avvisa_chi_ha_chiesto: avviso non scritto per la domanda %: %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END;
$$;

-- Funzioni dei trigger: nessuno le chiama a mano.
REVOKE EXECUTE ON FUNCTION public.domanda_avvisa_il_negozio() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.risposta_avvisa_chi_ha_chiesto() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS trg_domanda_avvisa_il_negozio ON public.product_questions;
CREATE TRIGGER trg_domanda_avvisa_il_negozio
  AFTER INSERT ON public.product_questions
  FOR EACH ROW EXECUTE FUNCTION public.domanda_avvisa_il_negozio();

DROP TRIGGER IF EXISTS trg_risposta_avvisa_chi_ha_chiesto ON public.product_questions;
CREATE TRIGGER trg_risposta_avvisa_chi_ha_chiesto
  AFTER UPDATE OF answer ON public.product_questions
  FOR EACH ROW EXECUTE FUNCTION public.risposta_avvisa_chi_ha_chiesto();

NOTIFY pgrst, 'reload schema';
